package com.example.bikerental;

import jakarta.validation.Valid;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.stream.Collectors;

@Controller
public class PortalController {
 private final BikeRepository bikes; private final CustomerRepository customers; private final RentalRepository rentals;
 private final UserAccountRepository accounts; private final FavoriteRepository favorites; private final ReviewRepository reviews;
 private final SupportTicketRepository tickets; private final CouponRepository coupons; private final MaintenanceRecordRepository maintenance;
 private final WaitlistEntryRepository waitlist; private final AppNotificationRepository notifications; private final VerificationRequestRepository verification;
 public PortalController(BikeRepository b, CustomerRepository c, RentalRepository r, UserAccountRepository a, FavoriteRepository f, ReviewRepository rv, SupportTicketRepository t, CouponRepository cp, MaintenanceRecordRepository m, WaitlistEntryRepository w, AppNotificationRepository n, VerificationRequestRepository v){bikes=b;customers=c;rentals=r;accounts=a;favorites=f;reviews=rv;tickets=t;coupons=cp;maintenance=m;waitlist=w;notifications=n;verification=v;}

 @GetMapping("/") public String landing(Model m, Authentication a){m.addAttribute("featuredBikes",bikes.findAll().stream().filter(Bike::isAvailable).limit(6).toList());m.addAttribute("bikeCount",bikes.count());m.addAttribute("availableCount",bikes.findByAvailableTrue().size());m.addAttribute("reviews",reviews.findAllByOrderByCreatedAtDesc().stream().limit(3).toList());m.addAttribute("signedIn",a!=null);return "index";}
 @GetMapping("/catalog") public String catalog(@RequestParam(required=false) String q,@RequestParam(required=false) String type,@RequestParam(required=false) BigDecimal maxPrice,@RequestParam(required=false) String location,Model m){List<Bike> all=bikes.findAll();List<Bike> filtered=all.stream().filter(b->"READY".equalsIgnoreCase(b.getMaintenanceStatus())).filter(b->q==null||q.isBlank()||(b.getName()+" "+b.getBrand()+" "+b.getBikeType()).toLowerCase().contains(q.toLowerCase())).filter(b->type==null||type.isBlank()||b.getBikeType().equalsIgnoreCase(type)).filter(b->maxPrice==null||b.getDailyRate().compareTo(maxPrice)<=0).filter(b->location==null||location.isBlank()||(b.getLocation()!=null&&b.getLocation().toLowerCase().contains(location.toLowerCase()))).toList();m.addAttribute("bikes",filtered);m.addAttribute("q",q);m.addAttribute("type",type);m.addAttribute("maxPrice",maxPrice);m.addAttribute("location",location);m.addAttribute("types",all.stream().map(Bike::getBikeType).filter(Objects::nonNull).distinct().toList());m.addAttribute("allBikes",all);return "catalog";}
 @GetMapping("/bike/{id}") public String bikeDetail(@PathVariable Long id,Model m){Bike b=bikes.findById(id).orElseThrow();m.addAttribute("bike",b);m.addAttribute("reviews",reviews.findByBikeIdOrderByCreatedAtDesc(id));return "bike-detail";}

 @GetMapping("/customer/dashboard") public String customerDashboard(Authentication a,Model m){UserAccount u=account(a);Customer c=customer(u);List<Rental> mine=rentals.findAllByCustomerEmailOrderByStartTimeDesc(c.getEmail());m.addAttribute("customer",c);m.addAttribute("account",u);m.addAttribute("bikes",bikes.findByAvailableTrue().stream().limit(6).toList());m.addAttribute("rentals",mine);m.addAttribute("favorites",favorites.findByUsernameOrderByCreatedAtDesc(a.getName()));m.addAttribute("notifications",notifications.findByUsernameOrderByCreatedAtDesc(a.getName()).stream().limit(8).toList());m.addAttribute("openTickets",tickets.findByUsernameOrderByCreatedAtDesc(a.getName()).stream().filter(t->"OPEN".equals(t.getStatus())).count());return "customer-dashboard";}
 @GetMapping("/customer/book/{id}") public String bookingForm(@PathVariable Long id,Authentication a,Model m){Bike b=bikes.findById(id).orElseThrow();m.addAttribute("bike",b);LocalDateTime min=LocalDateTime.now().plusHours(1).withSecond(0).withNano(0);m.addAttribute("minPickup",min);m.addAttribute("minPickupValue",min.format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")));m.addAttribute("defaultReturnValue",min.plusDays(1).format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")));m.addAttribute("coupons",coupons.findAll().stream().filter(Coupon::isActive).toList());m.addAttribute("loyaltyPoints",account(a).getLoyaltyPoints());return "booking";}
 @PostMapping("/customer/book/{id}") public String book(@PathVariable Long id,Authentication a,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime pickup,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime dropoff,@RequestParam(required=false) String couponCode,@RequestParam(defaultValue="false") boolean helmet,@RequestParam(defaultValue="false") boolean phoneHolder,@RequestParam(defaultValue="false") boolean luggageBox,@RequestParam(defaultValue="false") boolean agreementAccepted,@RequestParam(defaultValue="false") boolean usePoints,RedirectAttributes f){Bike b=bikes.findById(id).orElseThrow();if(!"READY".equalsIgnoreCase(b.getMaintenanceStatus())){f.addFlashAttribute("errorMessage","This bike is under maintenance or inspection.");return "redirect:/catalog";}if(!agreementAccepted){f.addFlashAttribute("errorMessage","Please accept the rental agreement before confirming.");return "redirect:/customer/book/"+id;}if(pickup==null||dropoff==null||pickup.isBefore(LocalDateTime.now())||!dropoff.isAfter(pickup)){f.addFlashAttribute("errorMessage","Choose a future pickup and a return time after pickup.");return "redirect:/customer/book/"+id;}boolean overlap=rentals.findAll().stream().filter(r->r.getBike().getId().equals(id)&&!List.of("CANCELLED","COMPLETED").contains(r.getStatus())).anyMatch(r->{LocalDateTime s=r.getScheduledPickup()!=null?r.getScheduledPickup():r.getStartTime();LocalDateTime e=r.getScheduledReturn()!=null?r.getScheduledReturn():(r.getEndTime()!=null?r.getEndTime():LocalDateTime.MAX);return s!=null&&pickup.isBefore(e)&&dropoff.isAfter(s);});if(overlap){f.addFlashAttribute("errorMessage","That bike is already booked for part of your selected time. Choose another time or bike.");return "redirect:/customer/book/"+id;}
 UserAccount u=account(a);Customer c=customer(u);long hours=Math.max(1,(ChronoUnit.MINUTES.between(pickup,dropoff)+59)/60);BigDecimal amount=b.getHourlyRate().multiply(BigDecimal.valueOf(hours));if(hours>=24)amount=b.getDailyRate().multiply(BigDecimal.valueOf(Math.ceil(hours/24.0)));if(pickup.getDayOfWeek()==DayOfWeek.SATURDAY||pickup.getDayOfWeek()==DayOfWeek.SUNDAY)amount=amount.multiply(new BigDecimal("1.10"));if(hours>=72)amount=amount.multiply(new BigDecimal("0.90"));if(helmet)amount=amount.add(new BigDecimal("100"));if(phoneHolder)amount=amount.add(new BigDecimal("50"));if(luggageBox)amount=amount.add(new BigDecimal("150"));String applied=null;if(couponCode!=null&&!couponCode.isBlank()){Optional<Coupon> co=coupons.findByCodeIgnoreCase(couponCode.trim());if(co.isPresent()&&co.get().isActive()){amount=amount.multiply(BigDecimal.valueOf(100-co.get().getDiscountPercent())).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP);applied=co.get().getCode();}}
 int pointsUsed=0;if(usePoints&&u.getLoyaltyPoints()>=100){pointsUsed=Math.min(u.getLoyaltyPoints(),amount.multiply(new BigDecimal("0.25")).setScale(0,RoundingMode.DOWN).intValue());if(pointsUsed>=100){amount=amount.subtract(BigDecimal.valueOf(pointsUsed));u.setLoyaltyPoints(u.getLoyaltyPoints()-pointsUsed);accounts.save(u);}else pointsUsed=0;}Rental r=new Rental();r.setBike(b);r.setCustomer(c);r.setScheduledPickup(pickup);r.setScheduledReturn(dropoff);r.setStartTime(pickup);r.setStatus("BOOKED");r.setTotalAmount(amount.setScale(2,RoundingMode.HALF_UP));r.setCouponCode(applied);r.setDepositAmount(new BigDecimal("1000.00"));r.setDepositStatus("PENDING");r.setAgreementAccepted(true);rentals.save(r);notifications.save(new AppNotification(a.getName(), "Booking " + r.getBookingCode() + " created. Estimated total: ₹" + r.getTotalAmount() + ". Deposit status: pending." + (pointsUsed > 0 ? " Points redeemed: " + pointsUsed : "")));f.addFlashAttribute("message","Booking confirmed: "+r.getBookingCode()+". Complete demo checkout from your dashboard.");return "redirect:/customer/dashboard";}
 @GetMapping("/customer/rental/{id}/edit") public String editBooking(@PathVariable Long id,Authentication a,Model m){Customer c=customer(account(a));Rental r=rentals.findByIdAndCustomerEmail(id,c.getEmail()).orElseThrow();if(!"BOOKED".equals(r.getStatus()))return "redirect:/customer/dashboard";m.addAttribute("rental",r);LocalDateTime min=LocalDateTime.now().plusHours(1).withSecond(0).withNano(0);m.addAttribute("minPickupValue",min.format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")));m.addAttribute("pickupValue",r.getScheduledPickup().format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")));m.addAttribute("returnValue",r.getScheduledReturn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")));return "edit-booking";}
 @PostMapping("/customer/rental/{id}/edit") public String updateBooking(@PathVariable Long id,Authentication a,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime pickup,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime dropoff,RedirectAttributes f){Customer c=customer(account(a));Rental r=rentals.findByIdAndCustomerEmail(id,c.getEmail()).orElseThrow();if(!"BOOKED".equals(r.getStatus())){f.addFlashAttribute("errorMessage","Only upcoming bookings can be modified.");return "redirect:/customer/dashboard";}if(pickup.isBefore(LocalDateTime.now())||!dropoff.isAfter(pickup)){f.addFlashAttribute("errorMessage","Choose a future pickup and a later return time.");return "redirect:/customer/rental/"+id+"/edit";}boolean overlap=rentals.findAll().stream().filter(x->!x.getId().equals(id)&&x.getBike().getId().equals(r.getBike().getId())&&!List.of("CANCELLED","COMPLETED").contains(x.getStatus())).anyMatch(x->{LocalDateTime st=x.getScheduledPickup()!=null?x.getScheduledPickup():x.getStartTime();LocalDateTime en=x.getScheduledReturn()!=null?x.getScheduledReturn():(x.getEndTime()!=null?x.getEndTime():LocalDateTime.MAX);return st!=null&&pickup.isBefore(en)&&dropoff.isAfter(st);});if(overlap){f.addFlashAttribute("errorMessage","The bike is already booked during those times.");return "redirect:/customer/rental/"+id+"/edit";}long hours=Math.max(1,(ChronoUnit.MINUTES.between(pickup,dropoff)+59)/60);BigDecimal amount=hours>=24?r.getBike().getDailyRate().multiply(BigDecimal.valueOf(Math.ceil(hours/24.0))):r.getBike().getHourlyRate().multiply(BigDecimal.valueOf(hours));r.setScheduledPickup(pickup);r.setScheduledReturn(dropoff);r.setStartTime(pickup);r.setTotalAmount(amount.setScale(2,RoundingMode.HALF_UP));rentals.save(r);notifications.save(new AppNotification(a.getName(),"Booking "+r.getBookingCode()+" has been updated."));f.addFlashAttribute("message","Booking updated successfully.");return "redirect:/customer/dashboard";}
 @PostMapping("/customer/rental/{id}/cancel") public String cancel(@PathVariable Long id,Authentication a,RedirectAttributes f){Customer c=customer(account(a));Rental r=rentals.findByIdAndCustomerEmail(id,c.getEmail()).orElse(null);if(r==null||!"BOOKED".equals(r.getStatus())){f.addFlashAttribute("errorMessage","Only upcoming bookings can be cancelled.");}else{r.setStatus("CANCELLED");rentals.save(r);bikes.findById(r.getBike().getId()).ifPresent(b->{b.setAvailable(true);bikes.save(b);});f.addFlashAttribute("message","Booking cancelled according to the demo cancellation policy. Admin can process any eligible refund.");}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/rental/{id}/pay") public String pay(@PathVariable Long id,Authentication a,RedirectAttributes f){Customer c=customer(account(a));Rental r=rentals.findByIdAndCustomerEmail(id,c.getEmail()).orElse(null);if(r==null||!"BOOKED".equals(r.getStatus())){f.addFlashAttribute("errorMessage","Booking not found or not payable.");return "redirect:/customer/dashboard";}r.setPaymentPaid(true);r.setDepositStatus("HELD_DEMO");rentals.save(r);notifications.save(new AppNotification(a.getName(),"Demo checkout recorded for booking "+r.getBookingCode()+". No real payment was taken."));f.addFlashAttribute("message","Demo checkout complete. No real payment gateway is connected.");return "redirect:/customer/dashboard";}
 @PostMapping("/customer/rental/{id}/rebook") public String rebook(@PathVariable Long id,Authentication a,RedirectAttributes f){Customer c=customer(account(a));Rental r=rentals.findByIdAndCustomerEmail(id,c.getEmail()).orElse(null);if(r==null){f.addFlashAttribute("errorMessage","Rental not found.");return "redirect:/customer/dashboard";}return "redirect:/customer/book/"+r.getBike().getId();}
 @PostMapping("/customer/favorite/{id}") public String favorite(@PathVariable Long id,Authentication a,RedirectAttributes f){Bike b=bikes.findById(id).orElseThrow();if(favorites.existsByUsernameAndBikeId(a.getName(),id))favorites.deleteByUsernameAndBikeId(a.getName(),id);else favorites.save(new Favorite(a.getName(),b));f.addFlashAttribute("message","Favourite list updated.");return "redirect:/catalog";}
 @GetMapping("/customer/favorites") public String favoritePage(Authentication a,Model m){m.addAttribute("favorites",favorites.findByUsernameOrderByCreatedAtDesc(a.getName()));return "favorites";}
 @PostMapping("/customer/waitlist/{id}") public String joinWaitlist(@PathVariable Long id,Authentication a,RedirectAttributes f){Bike b=bikes.findById(id).orElseThrow();if(!waitlist.existsByUsernameAndBikeIdAndNotifiedFalse(a.getName(),id))waitlist.save(new WaitlistEntry(a.getName(),b));f.addFlashAttribute("message","You have joined the availability waitlist. In-app alerts appear when admin releases the bike.");return "redirect:/catalog";}
 @PostMapping("/admin/bikes/{id}/release") public String releaseBike(@PathVariable Long id,RedirectAttributes f){Bike b=bikes.findById(id).orElseThrow();b.setMaintenanceStatus("READY");b.setAvailable(true);bikes.save(b);for(WaitlistEntry w:waitlist.findByBikeIdAndNotifiedFalse(id)){w.setNotified(true);waitlist.save(w);notifications.save(new AppNotification(w.getUsername(),"A bike you waitlisted for is available: "+b.getName()+"."));}f.addFlashAttribute("message","Bike marked ready; waitlisted users have in-app notifications.");return "redirect:/admin/maintenance";}

 @GetMapping("/customer/reviews") public String reviewPage(Model m){m.addAttribute("bikes",bikes.findAll());m.addAttribute("reviews",reviews.findAllByOrderByCreatedAtDesc());return "reviews";}
 @PostMapping("/customer/reviews") public String addReview(Authentication a,@RequestParam Long bikeId,@RequestParam int rating,@RequestParam String comment,RedirectAttributes f){if(rating<1||rating>5||comment==null||comment.isBlank()){f.addFlashAttribute("errorMessage","Choose a rating from 1 to 5 and add a comment.");return "redirect:/customer/reviews";}Bike b=bikes.findById(bikeId).orElseThrow();Customer owner=customer(account(a));boolean completed=rentals.findAllByCustomerEmailOrderByStartTimeDesc(owner.getEmail()).stream().anyMatch(r->r.getBike().getId().equals(bikeId)&&"COMPLETED".equals(r.getStatus()));if(!completed){f.addFlashAttribute("errorMessage","Reviews are accepted after a completed rental of that bike.");return "redirect:/customer/reviews";}UserAccount u=account(a);reviews.save(new Review(b,a.getName(),u.getName(),rating,comment.trim()));f.addFlashAttribute("message","Thanks for your review. Reviews are visible to other visitors.");return "redirect:/customer/reviews";}
 @GetMapping("/customer/support") public String support(Authentication a,Model m){m.addAttribute("tickets",tickets.findByUsernameOrderByCreatedAtDesc(a.getName()));return "support";}
 @PostMapping("/customer/support") public String createTicket(Authentication a,@RequestParam String subject,@RequestParam String message,RedirectAttributes f){if(subject.isBlank()||message.isBlank()){f.addFlashAttribute("errorMessage","Enter a subject and message.");return "redirect:/customer/support";}tickets.save(new SupportTicket(a.getName(),subject.trim(),message.trim()));f.addFlashAttribute("message","Support ticket created. You can track its status here.");return "redirect:/customer/support";}
 @GetMapping("/customer/notifications") public String userNotifications(Authentication a,Model m){List<AppNotification> ns=notifications.findByUsernameOrderByCreatedAtDesc(a.getName());ns.forEach(n->{n.setReadFlag(true);notifications.save(n);});m.addAttribute("notifications",ns);return "notifications";}
 @GetMapping("/customer/trip-planner") public String tripPlanner(){return "trip-planner";}
 @PostMapping("/customer/trip-planner") public String calculateTrip(@RequestParam double distance,@RequestParam(defaultValue="40") double mileage,@RequestParam BigDecimal dailyRate,Model m){double fuelLitres=mileage>0?distance/mileage:0;double fuelCost=fuelLitres*105.0;BigDecimal total=dailyRate.add(BigDecimal.valueOf(fuelCost));m.addAttribute("distance",distance);m.addAttribute("mileage",mileage);m.addAttribute("fuelCost",Math.round(fuelCost));m.addAttribute("totalEstimate",total.setScale(2,RoundingMode.HALF_UP));m.addAttribute("calculated",true);return "trip-planner";}
 @GetMapping("/customer/assistant") public String assistant(){return "assistant";}
 @PostMapping("/customer/assistant") public String assistantAnswer(@RequestParam String question,Model m){String q=question==null?"":question.toLowerCase();String answer;if(q.contains("price")||q.contains("cost")||q.contains("cheap")||q.contains("budget")){answer="Use the catalog price filter and compare hourly/daily rates. The booking page shows an estimate, selected extras, eligible coupons and a refundable-deposit status before confirmation.";}else if(q.contains("license")||q.contains("document")||q.contains("id")){answer="Bring a valid driving licence and accepted identity document. Admin should verify the documents before handing over a bike; document upload and third-party verification need to be configured before real use.";}else if(q.contains("cancel")||q.contains("refund")){answer="Upcoming bookings can be cancelled from your dashboard. Refund and deposit decisions follow the rental policy and must be processed by staff; demo checkout does not move real money.";}else if(q.contains("available")||q.contains("bike")||q.contains("recommend")){answer="Open Find a Bike and filter by type, budget and pickup location. For touring, compare mileage and comfort; for city rides, look at commuter bikes and scooters.";}else if(q.contains("break")||q.contains("emergency")){answer="Stop in a safe location, contact the rental desk using the support page, and follow local emergency guidance. A real 24/7 assistance provider must be configured by the business.";}else{answer="I can help with bike selection, prices, bookings, cancellations, documents and support. For account-specific help, create a support ticket.";}m.addAttribute("question",question);m.addAttribute("answer",answer);return "assistant";}
 @GetMapping("/customer/profile") public String profile(Authentication a,Model m){m.addAttribute("account",account(a));m.addAttribute("customer",customer(account(a)));return "profile";}
 @PostMapping("/customer/profile") public String updateProfile(Authentication a,@RequestParam String name,@RequestParam String phone,RedirectAttributes f){if(name==null||name.isBlank()||phone==null||phone.isBlank()){f.addFlashAttribute("errorMessage","Name and phone are required.");return "redirect:/customer/profile";}UserAccount u=account(a);Customer c=customer(u);u.setName(name.trim());u.setPhone(phone.trim());c.setName(name.trim());c.setPhone(phone.trim());accounts.save(u);customers.save(c);notifications.save(new AppNotification(a.getName(),"Your profile was updated."));f.addFlashAttribute("message","Profile updated.");return "redirect:/customer/profile";}
 @GetMapping("/plans") public String plans(){return "plans";}
 @GetMapping("/rental-terms") public String rentalTerms(){return "rental-terms";}
 @GetMapping("/customer/rewards") public String rewards(Authentication a,Model m){UserAccount u=account(a);m.addAttribute("account",u);m.addAttribute("referralLink","/signup?ref="+u.getReferralCode());m.addAttribute("completedRentals",rentals.findAllByCustomerEmailOrderByStartTimeDesc(customer(u).getEmail()).stream().filter(r->"COMPLETED".equals(r.getStatus())).count());return "rewards";}

 @GetMapping("/customer/verification") public String verificationPage(Authentication a,Model m){m.addAttribute("verification",verification.findByUsername(a.getName()).orElse(null));return "verification";}
 @PostMapping("/customer/verification") public String submitVerification(Authentication a,@RequestParam String documentType,@RequestParam String lastFour,RedirectAttributes f){if(lastFour==null||!lastFour.matches("[A-Za-z0-9]{4}")){f.addFlashAttribute("errorMessage","Enter only the last four characters of the document reference. Do not submit the full ID number here.");return "redirect:/customer/verification";}VerificationRequest v=verification.findByUsername(a.getName()).orElse(new VerificationRequest(a.getName(),documentType,lastFour));v.setStatus("PENDING");verification.save(v);f.addFlashAttribute("message","Verification request submitted for admin review. This demo stores only the document type and last four characters.");return "redirect:/customer/verification";}
 @GetMapping("/admin/verification") public String adminVerification(Model m){m.addAttribute("requests",verification.findAllByOrderBySubmittedAtDesc());return "admin-verification";}
 @PostMapping("/admin/verification/{id}") public String updateVerification(@PathVariable Long id,@RequestParam String status,@RequestParam(required=false) String note,RedirectAttributes f){VerificationRequest v=verification.findById(id).orElseThrow();v.setStatus(List.of("PENDING","VERIFIED","REJECTED").contains(status)?status:"PENDING");v.setAdminNote(note);verification.save(v);notifications.save(new AppNotification(v.getUsername(),"Your document verification status is now "+v.getStatus()+"."));f.addFlashAttribute("message","Verification status updated.");return "redirect:/admin/verification";}
 @GetMapping("/customer/rental/{id}/invoice") public String invoice(@PathVariable Long id,Authentication a,Model m){Customer c=customer(account(a));Rental r=rentals.findByIdAndCustomerEmail(id,c.getEmail()).orElseThrow();m.addAttribute("rental",r);m.addAttribute("customer",c);return "invoice";}
 @GetMapping("/compare") public String compare(@RequestParam(name="ids",required=false) List<Long> ids,Model m){List<Bike> selected=ids==null?List.of():ids.stream().distinct().map(id->bikes.findById(id).orElse(null)).filter(Objects::nonNull).limit(4).toList();m.addAttribute("bikes",selected);m.addAttribute("allBikes",bikes.findAll());return "compare";}
 @PostMapping("/customer/group-booking") public String groupBooking(Authentication a,@RequestParam List<Long> bikeIds,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime pickup,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime dropoff,@RequestParam(defaultValue="false") boolean agreementAccepted,RedirectAttributes f){if(!agreementAccepted){f.addFlashAttribute("errorMessage","Accept the rental terms for the group booking.");return "redirect:/catalog";}if(bikeIds==null||bikeIds.size()<2||bikeIds.size()>5){f.addFlashAttribute("errorMessage","Select between 2 and 5 bikes for a group booking.");return "redirect:/catalog";}if(pickup.isBefore(LocalDateTime.now())||!dropoff.isAfter(pickup)){f.addFlashAttribute("errorMessage","Choose a valid future pickup and return time.");return "redirect:/catalog";}Customer c=customer(account(a));List<Bike> chosen=bikeIds.stream().distinct().map(id->bikes.findById(id).orElseThrow()).toList();for(Bike b:chosen){if(!"READY".equalsIgnoreCase(b.getMaintenanceStatus())){f.addFlashAttribute("errorMessage","One selected bike is under maintenance or inspection. No group booking was created.");return "redirect:/catalog";}boolean clash=rentals.findAll().stream().filter(r->r.getBike().getId().equals(b.getId())&&!List.of("CANCELLED","COMPLETED").contains(r.getStatus())).anyMatch(r->{LocalDateTime st=r.getScheduledPickup()!=null?r.getScheduledPickup():r.getStartTime();LocalDateTime en=r.getScheduledReturn()!=null?r.getScheduledReturn():(r.getEndTime()!=null?r.getEndTime():LocalDateTime.MAX);return st!=null&&pickup.isBefore(en)&&dropoff.isAfter(st);});if(clash){f.addFlashAttribute("errorMessage","One selected bike is unavailable during those times. No group booking was created.");return "redirect:/catalog";}}for(Bike b:chosen){long hours=Math.max(1,(ChronoUnit.MINUTES.between(pickup,dropoff)+59)/60);Rental r=new Rental();r.setBike(b);r.setCustomer(c);r.setScheduledPickup(pickup);r.setScheduledReturn(dropoff);r.setStartTime(pickup);r.setStatus("BOOKED");r.setTotalAmount(b.getHourlyRate().multiply(BigDecimal.valueOf(hours)).setScale(2,RoundingMode.HALF_UP));r.setAgreementAccepted(true);rentals.save(r);notifications.save(new AppNotification(a.getName(),"Group booking created: "+r.getBookingCode()+" for "+b.getName()+"."));}f.addFlashAttribute("message","Group booking created for "+chosen.size()+" bikes. Review each booking in your dashboard.");return "redirect:/customer/dashboard";}
 @GetMapping("/admin") public String admin(Model m){List<Rental> rs=rentals.findAllByOrderByStartTimeDesc();m.addAttribute("bikeCount",bikes.count());m.addAttribute("availableCount",bikes.findByAvailableTrue().size());m.addAttribute("customerCount",customers.count());m.addAttribute("activeCount",rs.stream().filter(r->List.of("ACTIVE","BOOKED").contains(r.getStatus())).count());m.addAttribute("revenue",rs.stream().filter(r->"COMPLETED".equals(r.getStatus())).map(Rental::getTotalAmount).reduce(BigDecimal.ZERO,BigDecimal::add));m.addAttribute("rentals",rs.stream().limit(12).toList());return "admin-dashboard";}
 @GetMapping("/admin/bikes") public String adminBikes(Model m){m.addAttribute("bikes",bikes.findAll());return "admin-bikes";}
 @GetMapping("/admin/bikes/new") public String newBike(Model m){Bike b=new Bike();b.setHourlyRate(new BigDecimal("80"));b.setDailyRate(new BigDecimal("800"));m.addAttribute("bike",b);return "bike-form";}
 @GetMapping("/admin/bikes/edit/{id}") public String editBike(@PathVariable Long id,Model m){m.addAttribute("bike",bikes.findById(id).orElseThrow());return "bike-form";}
 @PostMapping("/admin/bikes/save") public String saveBike(@Valid @ModelAttribute Bike bike,org.springframework.validation.BindingResult result,Model m,RedirectAttributes f){BigDecimal oldDailyRate=bike.getId()==null?null:bikes.findById(bike.getId()).map(Bike::getDailyRate).orElse(null);if(bike.getId()==null&&bikes.findAll().stream().anyMatch(b->b.getRegistrationNumber().equalsIgnoreCase(bike.getRegistrationNumber())))result.rejectValue("registrationNumber","duplicate","Registration already exists");if(result.hasErrors())return "bike-form";if(bike.getMaintenanceStatus()==null)bike.setMaintenanceStatus("READY");if(bike.getLocation()==null)bike.setLocation("Chennai");bikes.save(bike);if(oldDailyRate!=null&&bike.getDailyRate()!=null&&bike.getDailyRate().compareTo(oldDailyRate)<0){for(Favorite fav:favorites.findByBikeId(bike.getId()))notifications.save(new AppNotification(fav.getUsername(),"Price drop: "+bike.getBrand()+" "+bike.getName()+" is now ₹"+bike.getDailyRate()+" per day."));}f.addFlashAttribute("message","Bike saved.");return "redirect:/admin/bikes";}
 @PostMapping("/admin/bikes/delete/{id}") public String deleteBike(@PathVariable Long id,RedirectAttributes f){if(rentals.existsByBikeIdAndStatus(id,"ACTIVE")||rentals.existsByBikeIdAndStatus(id,"BOOKED")){f.addFlashAttribute("errorMessage","Cannot delete a bike with an active booking.");}else bikes.deleteById(id);return "redirect:/admin/bikes";}
 @GetMapping("/admin/rentals") public String adminRentals(Model m){m.addAttribute("rentals",rentals.findAllByOrderByStartTimeDesc());return "admin-rentals";}
 @PostMapping("/admin/rentals/{id}/start") public String startRental(@PathVariable Long id,RedirectAttributes f){Rental r=rentals.findById(id).orElseThrow();if(!"BOOKED".equals(r.getStatus())){f.addFlashAttribute("errorMessage","Only confirmed bookings can be checked out.");return "redirect:/admin/rentals";}r.setStatus("ACTIVE");r.setStartTime(LocalDateTime.now());r.getBike().setAvailable(false);bikes.save(r.getBike());rentals.save(r);accounts.findAll().stream().filter(u->u.getEmail().equalsIgnoreCase(r.getCustomer().getEmail())).findFirst().ifPresent(u->notifications.save(new AppNotification(u.getUsername(),"Your bike rental has started.")));f.addFlashAttribute("message","Rental checked out.");return "redirect:/admin/rentals";}
 @PostMapping("/admin/rentals/{id}/return") public String returnBike(@PathVariable Long id,@RequestParam(defaultValue="false") boolean conditionOk,@RequestParam(required=false) String conditionNotes,@RequestParam(required=false) String conditionPhotoUrl,RedirectAttributes f){Rental r=rentals.findById(id).orElseThrow();if(!"ACTIVE".equals(r.getStatus())){f.addFlashAttribute("errorMessage","Only active rentals can be returned.");return "redirect:/admin/rentals";}LocalDateTime end=LocalDateTime.now();r.setEndTime(end);long minutes=Math.max(1,ChronoUnit.MINUTES.between(r.getStartTime(),end));long hours=Math.max(1,(minutes+59)/60);BigDecimal fee=r.getBike().getHourlyRate().multiply(BigDecimal.valueOf(hours));if(r.getScheduledReturn()!=null&&end.isAfter(r.getScheduledReturn())){long lateHours=Math.max(1,(ChronoUnit.MINUTES.between(r.getScheduledReturn(),end)+59)/60);fee=fee.add(r.getBike().getHourlyRate().multiply(BigDecimal.valueOf(lateHours)));}r.setTotalAmount(fee.setScale(2,RoundingMode.HALF_UP));r.setStatus("COMPLETED");r.setReturnConditionOk(conditionOk);r.setConditionNotes(conditionNotes);r.setConditionPhotoUrl(conditionPhotoUrl);r.setDepositStatus(conditionOk?"REFUND_DUE":"REVIEW_DAMAGE");Bike b=r.getBike();b.setAvailable(conditionOk);if(!conditionOk)b.setMaintenanceStatus("INSPECTION");bikes.save(b);rentals.save(r);BigDecimal finalFee=fee;accounts.findAll().stream().filter(u->u.getEmail().equalsIgnoreCase(r.getCustomer().getEmail())).findFirst().ifPresent(u->{u.setLoyaltyPoints(u.getLoyaltyPoints()+(int)Math.min(500,finalFee.intValue()/100));accounts.save(u);notifications.save(new AppNotification(u.getUsername(),"Rental returned. Final charge ₹"+finalFee+". Deposit status: "+r.getDepositStatus()+"."));});f.addFlashAttribute("message","Bike returned. Final charge: ₹"+finalFee+". Deposit: "+r.getDepositStatus());return "redirect:/admin/rentals";}
 @GetMapping("/admin/customers") public String adminCustomers(Model m){m.addAttribute("customers",customers.findAll());m.addAttribute("accounts",accounts.findAll());return "admin-customers";}
 @GetMapping("/admin/maintenance") public String maintenancePage(Model m){m.addAttribute("bikes",bikes.findAll());m.addAttribute("records",maintenance.findAllByOrderByServiceDateDesc());return "maintenance";}
 @PostMapping("/admin/maintenance") public String addMaintenance(@RequestParam Long bikeId,@RequestParam String notes,@RequestParam BigDecimal cost,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate nextServiceDate,RedirectAttributes f){Bike b=bikes.findById(bikeId).orElseThrow();b.setMaintenanceStatus("MAINTENANCE");b.setAvailable(false);bikes.save(b);MaintenanceRecord rec=new MaintenanceRecord(b,notes,LocalDate.now());rec.setCost(cost);rec.setNextServiceDate(nextServiceDate);maintenance.save(rec);f.addFlashAttribute("message","Maintenance record saved and bike made unavailable.");return "redirect:/admin/maintenance";}
 @GetMapping("/admin/coupons") public String couponPage(Model m){m.addAttribute("coupons",coupons.findAll());return "coupons";}
 @PostMapping("/admin/coupons") public String createCoupon(@RequestParam String code,@RequestParam int discountPercent,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate expiryDate,RedirectAttributes f){if(code.isBlank()||discountPercent<1||discountPercent>70){f.addFlashAttribute("errorMessage","Coupon needs a code and discount between 1% and 70%.");return "redirect:/admin/coupons";}Coupon c=new Coupon(code.trim().toUpperCase(),discountPercent,expiryDate);coupons.save(c);f.addFlashAttribute("message","Coupon created.");return "redirect:/admin/coupons";}
 @PostMapping("/admin/coupons/{id}/toggle") public String toggleCoupon(@PathVariable Long id,RedirectAttributes f){Coupon c=coupons.findById(id).orElseThrow();c.setActive(!c.isActive());coupons.save(c);f.addFlashAttribute("message","Coupon status updated.");return "redirect:/admin/coupons";}
 @GetMapping("/admin/support") public String adminSupport(Model m){m.addAttribute("tickets",tickets.findAllByOrderByCreatedAtDesc());return "admin-support";}
 @PostMapping("/admin/support/{id}/reply") public String replyTicket(@PathVariable Long id,@RequestParam String reply,@RequestParam String status,RedirectAttributes f){SupportTicket t=tickets.findById(id).orElseThrow();t.setAdminReply(reply);t.setStatus(List.of("OPEN","IN_PROGRESS","RESOLVED").contains(status)?status:"OPEN");tickets.save(t);notifications.save(new AppNotification(t.getUsername(),"Support ticket #"+id+" updated: "+t.getStatus()+"."));f.addFlashAttribute("message","Ticket updated.");return "redirect:/admin/support";}
 @GetMapping("/admin/reports") public String reports(Model m){List<Rental> rs=rentals.findAllByOrderByStartTimeDesc();BigDecimal revenue=rs.stream().filter(r->"COMPLETED".equals(r.getStatus())).map(Rental::getTotalAmount).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Long> byStatus=rs.stream().collect(Collectors.groupingBy(Rental::getStatus,Collectors.counting()));Map<String,Long> popular=rs.stream().collect(Collectors.groupingBy(r->r.getBike().getBrand()+" "+r.getBike().getName(),Collectors.counting()));m.addAttribute("rentals",rs);BigDecimal expenses=maintenance.findAllByOrderByServiceDateDesc().stream().map(MaintenanceRecord::getCost).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);m.addAttribute("expenses",expenses);m.addAttribute("profit",revenue.subtract(expenses));m.addAttribute("revenue",revenue);m.addAttribute("byStatus",byStatus);m.addAttribute("popular",popular);m.addAttribute("totalBookings",rs.size());m.addAttribute("completedCount",rs.stream().filter(r->"COMPLETED".equals(r.getStatus())).count());m.addAttribute("customers",customers.count());return "reports";}
 @GetMapping("/admin/reports.csv") public ResponseEntity<String> reportCsv(){StringBuilder s=new StringBuilder("Booking,Customer,Bike,Status,Amount,Pickup,Return\n");for(Rental r:rentals.findAllByOrderByStartTimeDesc())s.append(r.getBookingCode()).append(',').append(csv(r.getCustomer().getName())).append(',').append(csv(r.getBike().getName())).append(',').append(r.getStatus()).append(',').append(r.getTotalAmount()).append(',').append(r.getScheduledPickup()).append(',').append(r.getScheduledReturn()).append('\n');return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=rideloop-booking-report.csv").contentType(MediaType.parseMediaType("text/csv")).body(s.toString());}
 private String csv(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
 private UserAccount account(Authentication a){return accounts.findByUsername(a.getName()).orElseThrow();}
 private Customer customer(UserAccount u){return customers.findByEmail(u.getEmail()).orElseThrow();}
}
